class CountingNode(TreeNode):
    # a TreeNode that counts how often anyone looks at a child, so a test can tell one visit per node from repeated work
    looks = 0

    @property
    def left(self):
        CountingNode.looks += 1
        return self._left

    @left.setter
    def left(self, value):
        self._left = value

    @property
    def right(self):
        CountingNode.looks += 1
        return self._right

    @right.setter
    def right(self, value):
        self._right = value
def tree_from(levels, node_class=TreeNode):
    # [1, 2, 3, 4, 5]: level by level, left to right, None for a missing child (a missing node has no children listed)
    nodes = [None if v is None else node_class(v) for v in levels]
    children = iter(nodes[1:])
    for node in nodes:
        if node is not None:
            node.left = next(children, None)
            node.right = next(children, None)
    return nodes[0] if nodes else None
def diameter_of(levels):
    return tree_diameter(tree_from(levels))
def diameter_in_one_pass(levels):
    # the same, but fails when the nodes are looked at far more often than visiting each of them once would need
    size = sum(v is not None for v in levels)
    root = tree_from(levels, CountingNode)
    CountingNode.looks = 0
    answer = tree_diameter(root)
    if CountingNode.looks > 10 * size:
        raise AssertionError(f"too much repeated work: the children of {size} nodes were looked at {CountingNode.looks} times; visit every node once")
    return answer
def leaning_left(n):
    # one path of n nodes, each the left child of the one before
    levels = [1]
    for value in range(2, n + 1):
        levels += [value, None]
    return levels
def v_shape(arm):
    # a root with a path of `arm` nodes hanging below each of its two children
    levels, value = [1, 2, 3], 3
    for _ in range(arm - 1):
        levels += [value + 1, None, value + 2, None]
        value += 2
    return levels

