class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def tree_diameter(root):
    longest = 0

    def depth(node):
        """Number of nodes on the longest path from `node` down to a leaf (0 for no node)."""
        nonlocal longest
        if node is None:
            return 0
        left = depth(node.left)
        right = depth(node.right)
        longest = max(longest, left + right)      # the longest path that bends at this node has left + right edges
        return 1 + max(left, right)

    depth(root)
    return longest
